params.fn:
function(ctx){
  var name=String(ctx.templateName||'').trim();
  if(!name){return {ok:false,error:'templateName 为空'};}
  var cards=document.querySelectorAll('.template-card');
  for(var i=0;i<cards.length;i++){
    var t=cards[i].querySelector('.template-title');
    if(t&&(t.textContent||'').trim()===name){cards[i].click();return {ok:true,template:name};}
  }
  return {ok:false,error:'未找到模板',template:name};
}
